// behavior: it returns git's combined output and error so a test can exercise a
// push that partially fails (e.g. one of several push URLs is unreachable, which
// makes git exit non-zero even though the reachable URL received everything).
func (env *TestEnv) GitPushWithHooksAllowError(remote, refSpec string) (string, error) {
