// reconcileRefAcrossPushURLs runs fetch+replay recovery against every URL a push
// to target delivers to, not just the one `git fetch <target>` happens to read.
//
// A remote can carry several push URLs, and git pushes to all of them, so a
// rejected push may have been rejected by any subset. Reconciling only the
// remote's fetch URL leaves the others diverged with no path back.
//
// A single-destination target keeps the old behavior exactly — reconcile against
// the target as given, so a remote name still updates its remote-tracking ref.
// Enumeration failures fall back to the same single-target path.
func reconcileRefAcrossPushURLs(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	targets := resolveReconcileTargets(ctx, target)
	if len(targets) == 1 {
		return fetchAndRebaseRefCommon(ctx, targets[0], ref)
	}

	// Split the caller's remaining budget across the URLs, reserving one slice
	// for the retry push that follows, so one unreachable mirror in a set cannot
	// consume the whole pre-push budget.
	perURL := perTargetReconcileBudget(ctx, len(targets)+1)

	var firstErr error
	reconciled := 0
	for _, t := range targets {
		urlCtx := ctx
		var cancel context.CancelFunc
		if perURL > 0 {
			urlCtx, cancel = context.WithTimeout(ctx, perURL)
		}
		err := fetchAndRebaseRefCommon(urlCtx, t, ref)
		if cancel != nil {
			cancel()
		}
		if err != nil {
			logging.Warn(ctx, "checkpoint push recovery: reconcile against push URL failed",
				slog.String("ref", ref.String()),
				slog.String("url", remote.RedactURL(t)),
				slog.String("error", err.Error()),
			)
			if firstErr == nil {
				firstErr = err
			}
			continue
		}
		reconciled++
	}

	// Every URL failed — surface it as the single-target path would.
	if reconciled == 0 {
		return firstErr
	}
	if firstErr != nil {
		logging.Info(ctx, "checkpoint push recovery: reconciled some push URLs",
			slog.String("ref", ref.String()),
			slog.Int("reconciled", reconciled),
			slog.Int("total", len(targets)),
		)
	}
	return nil
}

// resolveReconcileTargets returns the destinations recovery must reconcile
// against for target. A URL is its own only destination. A remote name is
// expanded to its push URLs only when there is more than one — with a single
// push URL the name itself is the better target, since fetching by name updates
// the remote-tracking ref that pushRefIfNeeded's up-to-date check consults.
func resolveReconcileTargets(ctx context.Context, target string) []string {
	if remote.IsURL(target) {
		return []string{target}
	}
	urls, err := remote.GetPushURLs(ctx, target)
	if err != nil {
		logging.Debug(ctx, "checkpoint push recovery: could not enumerate push URLs; reconciling by remote name",
			slog.String("target", target),
			slog.String("error", err.Error()),
		)
		return []string{target}
	}
	if len(urls) < 2 {
		return []string{target}
	}
	return urls
}

// perTargetReconcileBudget divides the time left on ctx into slices. Returns 0
// when ctx carries no deadline (or none is left), meaning "impose no sub-budget".
func perTargetReconcileBudget(ctx context.Context, slices int) time.Duration {
	deadline, ok := ctx.Deadline()
	if !ok || slices <= 0 {
		return 0
	}
	remaining := time.Until(deadline)
	if remaining <= 0 {
		return 0
	}
	return remaining / time.Duration(slices)
}

